package com.nigson.commerce.engagement;

import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.function.Function;
import org.springframework.security.access.AccessDeniedException;import tools.jackson.databind.JsonNode;

/** Session-bound Commerce BFF for the Experience-owned engagement APIs. */
public final class EngagementRelay {
 public record Result(int status,JsonNode body){}
 private final URI base;private final HttpClient http;private final Function<PrivateWorkload.Route,String> credentials;private final ActorDelegation delegation;private final JdbcSessionTrust sessions;private final CommerceAuthority authority;
 public EngagementRelay(String env,String endpoint,Function<PrivateWorkload.Route,String> credentials,ActorDelegation delegation,JdbcSessionTrust sessions,CommerceAuthority authority){base=PhoneTarget.target(env,endpoint);this.credentials=Objects.requireNonNull(credentials);this.delegation=Objects.requireNonNull(delegation);this.sessions=Objects.requireNonNull(sessions);this.authority=Objects.requireNonNull(authority);http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
 public Result execute(ActorAssertion.Actor claimed,String session,String api,String path,String query,JsonNode body,String key,String match,String csrf,UUID correlation){IdentityKeys.outsideTransaction();Set<String> supported=Set.of("API-096","API-098","API-108","API-176","API-078","API-079","API-080","API-081","API-082","API-083","API-086");if(!supported.contains(api)||correlation==null)throw ApiValues.invalid();var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)&&r.owner().equals("experience")&&r.client().equals("nigson-commerce")).findFirst().orElseThrow(ActorAssertion::denied);boolean read=Set.of("API-176","API-083").contains(api);if(!route.method().equals(read?"GET":api.equals("API-086")?"PUT":"POST")||!path.matches(route.path().replace("{id}","[0-9a-fA-F-]{36}").replace("/","\\/")))throw ActorAssertion.denied();if(!path.matches("/[A-Za-z0-9_./-]{1,300}")||query!=null&&!query.matches("[A-Za-z0-9_=&%.,-]{1,1000}"))throw ApiValues.invalid();var current=authority.resolve(sessions.read(session,true),null,Set.of());if(claimed==null||!current.party().equals(claimed.party())||!current.roles().equals(claimed.roles())||claimed.organization()!=null)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);String role=switch(api){case "API-096"->"CUSTOMER";case "API-108"->"SALES";case "API-081","API-082"->"CONTENT_PUBLISHER";case "API-086"->"ADMIN";case "API-078","API-079","API-080","API-083"->"CONTENT_EDITOR";default->"CONTENT_PUBLISHER";};if(role.equals("CUSTOMER")){if(!current.roles().contains("CUSTOMER"))throw ActorAssertion.denied();}else authority.requireRole(current,role);boolean versioned=Set.of("API-079","API-080","API-081","API-082","API-086","API-098").contains(api);if(versioned&&(match==null||!match.matches("\"(0|[1-9][0-9]{0,18})\"")))throw ApiValues.invalid();if(!read){ApiValues.idempotencyKey(key);sessions.csrf(sessions.read(session,true),csrf);if(body==null)throw ApiValues.invalid();}else if(body!=null||key!=null)throw ApiValues.invalid();String scope=route.scope();byte[] bytes=read?new byte[0]:EventCodec.JSON.writeValueAsBytes(body);if(bytes.length>65536)throw ApiValues.invalid();String target=path+(query==null||query.isEmpty()?"":"?"+query);String assertion,token;try{var binding=new ActorAssertion.Binding("experience",scope,route.method(),path,correlation,ActorAssertion.Binding.bodyHash(bytes));assertion=delegation.issue(session,binding,null);token=credentials.apply(route);}catch(AccessDeniedException denied){throw denied;}catch(RuntimeException unavailable){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}if(token==null||token.isBlank()||token.length()>16384)throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);var b=HttpRequest.newBuilder(base.resolve(target)).timeout(Duration.ofSeconds(7)).header("Authorization","Bearer "+token).header("X-Nigson-Actor",assertion).header("X-Correlation-ID",correlation.toString()).header("Accept","application/json");if(!read)b.header("Content-Type","application/json").header("Idempotency-Key",key);if(match!=null)b.header("If-Match",match);String trace=com.nigson.shared.observability.WireContext.traceparent();if(trace!=null)b.header("traceparent",trace);HttpResponse<byte[]> response;try{response=http.send(b.method(route.method(),read?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofByteArray(bytes)).build(),x->new Limited(65536));}catch(Exception unavailable){if(unavailable instanceof InterruptedException)Thread.currentThread().interrupt();throw new Problem.Failure(read?ProblemCode.PROVIDER_UNAVAILABLE:ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}String content=response.headers().firstValue("Content-Type").orElse("").split(";",2)[0];try{JsonNode result=EventCodec.JSON.readTree(response.body());int expected=Set.of("API-096","API-108","API-078","API-079").contains(api)?201:200;if(response.statusCode()!=expected){if(content.equals("application/problem+json"))for(var code:ProblemCode.values())if(code.status==response.statusCode()&&code.name().equals(result.path("code").asString()))throw new Problem.Failure(code);throw new Problem.Failure(read?ProblemCode.PROVIDER_UNAVAILABLE:ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}if(!content.equals("application/json")||!result.isObject()&&read)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);return new Result(response.statusCode(),result);}catch(Problem.Failure safe){throw safe;}catch(Exception invalid){throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}}
 private static final class PhoneTarget{static URI target(String env,String endpoint){try{URI u=URI.create(endpoint);boolean local=Set.of("local","test").contains(env);if(u.getHost()==null||u.getUserInfo()!=null||u.getRawQuery()!=null||u.getFragment()!=null||!Set.of("","/").contains(u.getRawPath())||!(local?Set.of("http","https").contains(u.getScheme())&&Set.of("127.0.0.1","localhost","experience","experience-mock").contains(u.getHost()):"https".equals(u.getScheme())&&u.getHost().matches("[a-z0-9]+(?:[.-][a-z0-9]+)*\\.internal")))throw new IllegalArgumentException();return URI.create(u.getScheme()+"://"+u.getRawAuthority());}catch(RuntimeException bad){throw new IllegalArgumentException("EXPERIENCE_TARGET_REQUIRED");}}}
 private static final class Limited implements HttpResponse.BodySubscriber<byte[]>{private final CompletableFuture<byte[]> result=new CompletableFuture<>();private final java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();private final int max;private Flow.Subscription subscription;Limited(int max){this.max=max;}public CompletionStage<byte[]> getBody(){return result;}public void onSubscribe(Flow.Subscription s){subscription=s;s.request(1);}public void onNext(List<java.nio.ByteBuffer> items){for(var item:items){if(out.size()+item.remaining()>max){subscription.cancel();result.completeExceptionally(new IllegalArgumentException());return;}byte[] b=new byte[item.remaining()];item.get(b);out.writeBytes(b);}subscription.request(1);}public void onError(Throwable t){result.completeExceptionally(t);}public void onComplete(){result.complete(out.toByteArray());}}
}
